var COL_WIDTHS = {"Đơn vị điều hành":100,"AM chuyên quản":100,"Mã tỉnh":100,"Mã HĐ":100,"Tên khách hàng":120,"Nhóm sự cố":100,"Loại sự cố":100,"Chi tiết":300,"Ngày bắt đầu":100,"Ngày kết thúc":100,"Ngày hoàn thành":100,"Trạng thái":100,"Tên nhân viên":100,"Mã nhân viên":100,"Lĩnh vực":100,"Ngành hàng":100,"Sản phẩm":150,"Giai đoạn":100,"Hệ thống":100,"SĐT":100,"Địa chỉ":250,"Tuần":100};
var CT_GROUP   = 'bang_chitiet_group';
